public class METSalesOrderHeaderDualWriteUpdate extends RunBaseBatch implements BatchRetryable
{
    Integer            numOfRecords;

    DialogField        dlgNumOfRecords;

    QueryRun       queryRun;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        numOfRecords
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();
    ;
    dlgNumOfRecords       = dialog.addFieldValue(extendedtypestr(Integer), numOfRecords, "Number of records", "Number of open records that is ready to sync");
    dlgNumOfRecords.enabled(false);

    return dialog;
}

public boolean getFromDialog()
{
    ;
    numOfRecords        = dlgNumOfRecords.value();

    return super();
}

public Integer parmNumOfRecords(Integer _numOfRecords = numOfRecords)
{
    numOfRecords = _numOfRecords;
    return numOfRecords;
}

public void initQuery()
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tablenum(METSalesTable));
    QueryBuildRange         qBR;
    ;
    qBR = SysQuery::findOrCreateRange(qbds, fieldnum(METSalesTable, DualWriteRequired));
    qBR.value(queryValue(NoYes::Yes));
    qBR.status(RangeStatus::Locked);

    queryRun = new QueryRun(query);
}

public void calcNumOfRecords()
{
    numOfRecords = SysQuery::countTotal(new QueryRun(queryRun.query()));
}

public boolean unpack(container _packedClass)
{
    Version    version = RunBase::getVersion(_packedClass);
    container  queryCon;
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, queryCon] = _packedClass;
            if (SysQuery::isPackedOk(queryCon))
            {
                queryRun = new QueryRun(queryCon);
            }
            else
            {
                this.initQuery();
            }
            break;
        default:
            return false;
    }
    return true;
}

public void run()
{
    int                     processedCounter;
    METSalesTable           metSalesTable, metSalesTableUpdate;

    while (queryRun.next())
    {
        metSalesTable = queryRun.get(tablenum(METSalesTable));

        try
        {
            ttsbegin;

            metSalesTableUpdate = METSalesTable::findRecId(metSalesTable.RecId, true);

            if (metSalesTableUpdate)
            {
                metSalesTableUpdate.DualWriteRequired = NoYes::No;
                metSalesTableUpdate.update();
            }

            ttscommit;

            processedCounter++;
        }
        catch (Exception::Error)
        {
            ttsAbort;
            error(strFmt("METSalesOrderHeaderDualWriteUpdate: failed to update DualWriteRequired for SalesId %1 (RecId %2)", metSalesTable.SalesId, metSalesTable.RecId));
        }
        catch (Exception::Deadlock)
        {
            ttsAbort;
            error(strFmt("METSalesOrderHeaderDualWriteUpdate: deadlock while updating SalesId %1 (RecId %2)", metSalesTable.SalesId, metSalesTable.RecId));
        }
        catch (Exception::UpdateConflict)
        {
            ttsAbort;
            error(strFmt("METSalesOrderHeaderDualWriteUpdate: update conflict while updating SalesId %1 (RecId %2)", metSalesTable.SalesId, metSalesTable.RecId));
        }
    }

    info(strfmt(" %1 record(s) processed", processedCounter));
}

public static METSalesOrderHeaderDualWriteUpdate construct()
{
    return new METSalesOrderHeaderDualWriteUpdate();
}

static ClassDescription description()
{
    return "Dual write sales order header updates";
}

public static void main(Args _args)
{
    METSalesOrderHeaderDualWriteUpdate    runObject = METSalesOrderHeaderDualWriteUpdate::construct();
    ;
    if (runObject.prompt())
    {
        runObject.runOperation();
    }
}
